<?php declare(strict_types=1);namespace App\Controllers\Admin;use App\Core\DB;use App\Core\Request;use App\Core\Response;use App\Models\AuditLog;final class AuditController extends AdminController{public function index(Request $x):Response{$n=AuditLog::query()->select('t.*, u.email AS user_email')->join('LEFT JOIN '.DB::q(DB::table('users')).' u ON u.id = t.user_id')->orderBy('t.id','DESC');if($x->str('action')){$n->where('t.action','LIKE',$x->str('action').'%');}$n->search(['t.target','u.email','t.ip'],$x->str('q'));$Y=$n->paginate($this->pageNumber($x),50);$Y['items']=AuditLog::castAll($Y['items']);return $this->view('admin/audit',['res'=>$Y,'filters'=>['q'=>$x->str('q'),'action'=>$x->str('action')],'meta'=>['title'=>t('admin.audit')]]);}}